CREATE TYPE "UserRole" AS ENUM ('USER', 'ADMIN');
CREATE TYPE "SubmissionStatus" AS ENUM ('PENDING', 'APPROVED', 'REJECTED', 'CANCELLED');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "displayName" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" "UserRole" NOT NULL DEFAULT 'USER', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "RefreshToken" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "tokenHash" TEXT NOT NULL UNIQUE, "familyId" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "revokedAt" TIMESTAMP(3), "replacedBy" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Category" ("id" TEXT PRIMARY KEY, "slug" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL, "sortOrder" INTEGER NOT NULL DEFAULT 0, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Workflow" ("id" TEXT PRIMARY KEY, "slug" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL, "description" TEXT NOT NULL, "authorId" TEXT NOT NULL REFERENCES "User"("id"), "categoryId" TEXT NOT NULL REFERENCES "Category"("id"), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Submission" ("id" TEXT PRIMARY KEY, "workflowId" TEXT NOT NULL REFERENCES "Workflow"("id"), "authorId" TEXT NOT NULL REFERENCES "User"("id"), "categoryId" TEXT NOT NULL REFERENCES "Category"("id"), "version" TEXT NOT NULL, "revision" INTEGER NOT NULL, "status" "SubmissionStatus" NOT NULL DEFAULT 'PENDING', "manifest" JSONB NOT NULL, "sourceObjectKey" TEXT NOT NULL, "sourceSha256" TEXT NOT NULL, "clientCodeSha256" TEXT, "serverCodeSha256" TEXT NOT NULL, "reviewComment" TEXT, "reviewerId" TEXT REFERENCES "User"("id"), "reviewedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Release" ("id" TEXT PRIMARY KEY, "workflowId" TEXT NOT NULL REFERENCES "Workflow"("id"), "submissionId" TEXT NOT NULL UNIQUE REFERENCES "Submission"("id"), "version" TEXT NOT NULL, "manifest" JSONB NOT NULL, "keyId" TEXT NOT NULL, "signature" TEXT NOT NULL, "codeSha256" TEXT NOT NULL, "packageSha256" TEXT NOT NULL, "packageObjectKey" TEXT NOT NULL, "downloadCount" INTEGER NOT NULL DEFAULT 0, "publishedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY, "actorId" TEXT REFERENCES "User"("id"), "action" TEXT NOT NULL, "resourceType" TEXT NOT NULL, "resourceId" TEXT NOT NULL, "metadata" JSONB, "requestId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "Submission_workflowId_version_revision_key" ON "Submission"("workflowId", "version", "revision");
CREATE UNIQUE INDEX "Release_workflowId_version_key" ON "Release"("workflowId", "version");
CREATE INDEX "Submission_status_createdAt_idx" ON "Submission"("status", "createdAt");
CREATE INDEX "Release_publishedAt_idx" ON "Release"("publishedAt");
CREATE INDEX "RefreshToken_userId_familyId_idx" ON "RefreshToken"("userId", "familyId");
CREATE INDEX "AuditLog_createdAt_idx" ON "AuditLog"("createdAt");
